def find_rectangles(grid):
    """Find rectangular regions of uniform color that have some intruders"""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    visited = set()
    rectangles = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and (r, c) not in visited:
                # Find bounding box of all same-color pixels
                color = grid[r][c]
                cells = []
                for rr in range(h):
                    for cc in range(w):
                        if grid[rr][cc] == color:
                            if (rr, cc) == (r, c):
                                cells.append((rr, cc))
                                visited.add((rr, cc))

                if not cells:
                    continue

                # Find bounding box
                r0, c0 = min(p[0] for p in cells), min(p[1] for p in cells)
                r1, c1 = max(p[0] for p in cells), max(p[1] for p in cells)

                # Check if it contains intruders
                intruders = []
                is_rectangle = True
                rect_content = []

                for rr in range(r0, r1+1):
                    for cc in range(c0, c1+1):
                        if grid[rr][cc] == color:
                            if is_rectangle:
                                is_rectangle = False
                        else:
                            if grid[rr][cc] != 0:
                                intruders.append((rr, cc))

                # More systematic check for intruders
                for rr in range(r0, r1+1):
                    for cc in range(c0, c1+1):
                        val = grid[rr][cc]
                        if val == color:
                            continue
                        elif val == 0:
                            continue
                        else:
                            intruders.append((rr, cc))

                if intruders:
                    # Collect all same-color cells in this bounding box
                    all_in_box = [(rr, cc) for rr in range(r0, r1+1) for cc in range(c0, c1+1)]
                    main_color_cells = [(rr, cc) for rr, cc in all_in_box if grid[rr][cc] == color]

                    rectangles.append({
                        'box': (r0, c0, r1, c1),
                        'color': color,
                        'intruders': intruders,
                        'main_cells': main_color_cells
                    })

    return rectangles

